+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ *
+ * <p>The store can be configured through the following properties:</p>
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=...          # ignore, repair, or fail
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern ASCII_WORD_PATTERN = Pattern.compile("[A-Za-z0-9]{4,120}");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_DEFAULT = "random";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+    private static final Set<String> INTEGRITY_VALUES = new HashSet<>(Arrays.asList("repair", "fail", "ignore"));
+
+    /* The lock is shared by all instances using the same index in this process. */
+    private static final ConcurrentHashMap<String, StoreState> STORE_STATES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean customConstructorStrategy;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private StoreState storeState;
+    private RuleViolationFileNameStrategy activeStrategy;
+    private String integrityMode;
+
+    /**
+     * Creates a standard store that names rule violation files randomly.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = ruleDescription -> UUID.randomUUID().toString();
+        customConstructorStrategy = false;
+    }
+
+    /**
+     * Creates a store with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        constructorStrategy = Objects.requireNonNull(ruleViolationFileNameStrategy, "ruleViolationFileNameStrategy");
+        customConstructorStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        boolean configuredStoreCreationAllowed = Boolean.parseBoolean(
+                properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        boolean configuredStoreUpdateAllowed = Boolean.parseBoolean(
+                properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        String configuredIntegrity = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT);
+        if (!INTEGRITY_VALUES.contains(configuredIntegrity)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Invalid value '%s' for %s; accepted values are repair, fail and ignore",
+                    configuredIntegrity, INTEGRITY_PROPERTY_NAME));
+        }
+        if ("repair".equals(configuredIntegrity) && !configuredStoreUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s=true",
+                    ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        if (customConstructorStrategy && properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "%s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor",
+                    FILE_NAMES_PROPERTY_NAME));
+        }
+
+        RuleViolationFileNameStrategy configuredStrategy = customConstructorStrategy
+                ? constructorStrategy
+                : createConfiguredStrategy(properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_DEFAULT));
+
+        File configuredFolder;
+        try {
+            configuredFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).getCanonicalFile();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        String storeKey = new File(configuredFolder, STORED_RULES_FILE_NAME).getAbsolutePath();
+        StoreState state = STORE_STATES_BY_PATH.computeIfAbsent(storeKey, ignored -> new StoreState());
+
+        synchronized (state) {
+            prepareFolder(configuredFolder);
+            File indexFile = new File(configuredFolder, STORED_RULES_FILE_NAME);
+            boolean indexExists = existsWithoutFollowingLinks(indexFile.toPath());
+            if (indexExists && !Files.isRegularFile(indexFile.toPath())) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Violation store index %s is not a regular file directly in the store folder",
+                        indexFile.getAbsolutePath()));
+            }
+            if (!indexExists && !configuredStoreCreationAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+
+            Properties loadedProperties = indexExists ? loadProperties(indexFile) : new Properties();
+            IntegrityReport report = null;
+            boolean indexChanged = false;
+            if (!"ignore".equals(configuredIntegrity)) {
+                report = inspect(configuredFolder, loadedProperties, configuredStrategy);
+                if ("fail".equals(configuredIntegrity) && report.hasProblems()) {
+                    throw new StoreInitializationFailedException(report.toString());
+                }
+                if ("repair".equals(configuredIntegrity)) {
+                    indexChanged = repair(configuredFolder, loadedProperties, report);
+                }
+            }
+
+            if (!indexExists) {
+                createIndexFile(indexFile);
+            } else if (indexChanged) {
+                writePropertiesAtomically(indexFile, configuredFolder.toPath(), loadedProperties);
+            }
+
+            state.indexFile = indexFile;
+            state.folder = configuredFolder;
+            state.properties = loadedProperties;
+        }
+
+        storeCreationAllowed = configuredStoreCreationAllowed;
+        storeUpdateAllowed = configuredStoreUpdateAllowed;
+        storeFolder = configuredFolder;
+        storeState = state;
+        activeStrategy = configuredStrategy;
+        integrityMode = configuredIntegrity;
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(),
+                new File(configuredFolder, STORED_RULES_FILE_NAME).getAbsolutePath());
+    }
+
+    private RuleViolationFileNameStrategy createConfiguredStrategy(String configuredName) {
+        if ("random".equals(configuredName)) {
+            return ruleDescription -> UUID.randomUUID().toString();
+        }
+        if ("description".equals(configuredName)) {
+            return TextFileBasedViolationStore::createDescriptionFileName;
+        }
+        try {
+            Class<?> strategyType = Class.forName(configuredName);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Configured %s must implement %s: %s",
+                        FILE_NAMES_PROPERTY_NAME, RuleViolationFileNameStrategy.class.getName(), configuredName));
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s as a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    configuredName), e);
+        }
+    }
+
+    private static String createDescriptionFileName(String description) {
+        String selectedWord = null;
+        Matcher matcher = Pattern.compile("[A-Za-z0-9]+").matcher(description);
+        while (matcher.find()) {
+            String candidate = matcher.group();
+            if (ASCII_WORD_PATTERN.matcher(candidate).matches()) {
+                selectedWord = candidate;
+            }
+        }
+        String digest = digest(description);
+        if (selectedWord == null) {
+            selectedWord = digest;
+        }
+        String result = selectedWord + "-" + digest;
+        return result.length() <= 200 ? result : result.substring(0, 200);
+    }
+
+    private static String digest(String value) {
+        try {
+            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(bytes.length * 2);
+            for (byte aByte : bytes) {
+                result.append(String.format("%02x", aByte & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private void prepareFolder(File folder) {
+        Path folderPath = folder.toPath();
+        try {
+            if (existsWithoutFollowingLinks(folderPath)) {
+                if (!Files.isDirectory(folderPath)) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Violation store path %s is not a directory", folder.getAbsolutePath()));
+                }
+            } else {
+                Files.createDirectories(folderPath);
+            }
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadProperties(File indexFile) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(indexFile)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private void createIndexFile(File indexFile) {
+        try {
+            Files.createFile(indexFile.toPath());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeState) {
+            return storeState.properties.containsKey(normalize(rule.getDescription()));
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        synchronized (storeState) {
+            String description = normalize(rule.getDescription());
+            String existingFileName = storeState.properties.getProperty(description);
+            if (existingFileName != null && violations.isEmpty() && "repair".equals(integrityMode)) {
+                forgetRuleWithNoViolations(description, existingFileName);
+                return;
+            }
+
+            if (existingFileName == null && violations.isEmpty() && "repair".equals(integrityMode)) {
+                return;
+            }
+
+            if (existingFileName == null) {
+                existingFileName = nameForSave(rule.getDescription());
+                Path target = safeNewFilePath(existingFileName, storeState.properties);
+                writeViolationsAtomically(target, violations);
+                Properties updated = copyOf(storeState.properties);
+                updated.setProperty(description, ensureUnixLineBreaks(existingFileName));
+                try {
+                    writePropertiesAtomically(storeState.indexFile, storeState.folder.toPath(), updated);
+                } catch (RuntimeException e) {
+                    deleteIfExists(target);
+                    throw e;
+                }
+                storeState.properties = updated;
+                log.trace("Assigning new file {} to rule '{}'", existingFileName, description);
+                return;
+            }
+
+            Path target = safeExistingFilePath(existingFileName);
+            writeViolationsAtomically(target, violations);
+            log.trace("Rule '{}' is already stored in file {}", description, existingFileName);
+        }
+    }
+
+    private String nameForSave(String description) {
+        String result = activeStrategy.createRuleFileName(description);
+        if (result == null || result.trim().isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private void forgetRuleWithNoViolations(String description, String fileName) {
+        ResolvedFile resolved = resolveFile(fileName);
+        if (!resolved.lexicallyInside || resolved.resolvedOutside || resolved.isDirectory || resolved.isSpecial) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot forget rule '%s': its stored file is outside the store folder or is not a regular file",
+                    description));
+        }
+        if (resolved.isIndex || resolved.resolvedPath != null && isSameFile(resolved.resolvedPath, storeState.indexFile.toPath())) {
+            throw new StoreUpdateFailedException("A rule cannot use the stored.rules index as its violation file");
+        }
+
+        boolean shared = sharesFileWithAnotherEntry(description, fileName, resolved);
+        Properties oldProperties = storeState.properties;
+        Properties updated = copyOf(oldProperties);
+        updated.remove(description);
+        if (shared || !resolved.hasSomething()) {
+            writePropertiesAtomically(storeState.indexFile, storeState.folder.toPath(), updated);
+            storeState.properties = updated;
+            return;
+        }
+
+        DeletionBackup backup = moveToDeletionBackup(resolved);
+        try {
+            writePropertiesAtomically(storeState.indexFile, storeState.folder.toPath(), updated);
+            deleteBackup(backup);
+            storeState.properties = updated;
+        } catch (RuntimeException e) {
+            restoreBackup(backup);
+            try {
+                writePropertiesAtomically(storeState.indexFile, storeState.folder.toPath(), oldProperties);
+            } catch (RuntimeException restoreFailure) {
+                e.addSuppressed(restoreFailure);
+            }
+            throw e;
+        }
+    }
+
+    private boolean sharesFileWithAnotherEntry(String description, String fileName, ResolvedFile resolved) {
+        for (String otherDescription : storeState.properties.stringPropertyNames()) {
+            if (otherDescription.equals(description)) {
+                continue;
+            }
+            String otherName = storeState.properties.getProperty(otherDescription);
+            if (normalize(otherName).equals(normalize(fileName))) {
+                return true;
+            }
+            ResolvedFile other = resolveFile(otherName);
+            if (resolved.resolvedPath != null && other.resolvedPath != null
+                    && isSameFile(resolved.resolvedPath, other.resolvedPath)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeState) {
+            String ruleDetailsFileName = storeState.properties.getProperty(normalize(rule.getDescription()));
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(storeState.folder.toPath().resolve(ruleDetailsFileName).normalize());
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path file) {
+        String violationsText = readStoreFile(file);
+        if (violationsText.isEmpty() || onlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private boolean onlyLineBreaks(String text) {
+        for (int i = 0; i < text.length(); i++) {
+            if (text.charAt(i) != '\n' && text.charAt(i) != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            String result = new String(toByteArray(file.toFile()), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String normalize(String value) {
+        return ensureUnixLineBreaks(value);
+    }
+
+    private Path safeNewFilePath(String fileName, Properties properties) {
+        Path candidate = storeState.folder.toPath().resolve(fileName).normalize();
+        if (!isDirectChild(candidate) || fileName.equals(STORED_RULES_FILE_NAME)
+                || existsWithoutFollowingLinks(candidate)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write violation file '%s': the target is outside the store, is occupied, or is stored.rules",
+                    fileName));
+        }
+        for (String description : properties.stringPropertyNames()) {
+            Path recorded = storeState.folder.toPath().resolve(properties.getProperty(description)).normalize();
+            if (recorded.equals(candidate)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write violation file '%s': another entry records the target", fileName));
+            }
+        }
+        return candidate;
+    }
+
+    private Path safeExistingFilePath(String fileName) {
+        ResolvedFile resolved = resolveFile(fileName);
+        if (!resolved.lexicallyInside || resolved.resolvedOutside || resolved.isDirectory || resolved.isSpecial
+                || !resolved.hasSomething()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write violation file '%s': the recorded path is not a regular file directly in the store",
+                    fileName));
+        }
+        if (resolved.isIndex || resolved.resolvedPath != null && isSameFile(resolved.resolvedPath, storeState.indexFile.toPath())) {
+            throw new StoreUpdateFailedException("A rule cannot overwrite the stored.rules index");
+        }
+        return resolved.resolvedPath;
+    }
+
+    private void writeViolationsAtomically(Path target, List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeState.folder.toPath(), ".archunit-violation-", ".tmp");
+            Files.write(temporary, builder.toString().getBytes(UTF_8), StandardOpenOption.TRUNCATE_EXISTING);
+            moveReplacing(temporary, target);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                deleteIfExists(temporary);
+            }
+        }
+    }
+
+    private static void writePropertiesAtomically(File indexFile, Path folder, Properties properties) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(folder, ".archunit-index-", ".tmp");
