    private static void restoreBackup(DeletionBackup backup) {
        try {
            if (backup.linkBackup != null) {
                Files.move(backup.linkBackup, backup.recordedPath, StandardCopyOption.REPLACE_EXISTING);
                Files.move(backup.targetBackup, backup.resolvedPath, StandardCopyOption.REPLACE_EXISTING);
            } else {
                Files.move(backup.targetBackup, backup.recordedPath, StandardCopyOption.REPLACE_EXISTING);
            }
        } catch (IOException ignored) {
            // The original failure is more useful to the caller; the store remains protected by the index transaction.
        }
    }

