    private IntegrityReport inspect(File folder, Properties properties, RuleViolationFileNameStrategy strategy) {
        List<Entry> entries = new ArrayList<>();
        List<String> descriptions = new ArrayList<>(properties.stringPropertyNames());
        Collections.sort(descriptions);
        for (String description : descriptions) {
            String recordedName = properties.getProperty(description);
            String derivedName = nameForInspection(strategy, description);
            ResolvedFile resolved = resolveFile(folder, recordedName);
            Entry entry = new Entry(description, recordedName, derivedName, resolved);
            entry.broken = !resolved.isValidRegularFile();
            entry.resolvedViolations = entry.isValid() && readLines(resolved.resolvedPath).isEmpty();
            entry.misplaced = !recordedName.equals(derivedName);
            entries.add(entry);
        }

    private static ResolvedFile resolveFile(File folder, String fileName) {
        Path folderPath = folder.toPath();
        Path recordedPath = folderPath.resolve(fileName).normalize();
        boolean lexicallyInside = isDirectChild(recordedPath, folderPath);
        if (!lexicallyInside) {
            return new ResolvedFile(recordedPath, false, false, false, false, null, false);
        }
        boolean exists = existsWithoutFollowingLinks(recordedPath);
        boolean symbolicLink = Files.isSymbolicLink(recordedPath);
        if (!exists) {
            return new ResolvedFile(recordedPath, true, false, false, false, null, symbolicLink);
        }
        try {
            Path resolvedPath = recordedPath.toRealPath();
            boolean outside = !resolvedPath.getParent().equals(folderPath.toRealPath());
            boolean directory = Files.isDirectory(resolvedPath);
            boolean regular = Files.isRegularFile(resolvedPath);
            boolean special = !directory && !regular;
            return new ResolvedFile(recordedPath, true, outside, directory, special, resolvedPath, symbolicLink);
        } catch (IOException e) {
            return new ResolvedFile(recordedPath, true, false, false, false, null, symbolicLink);
        }
    }

    private static boolean isDirectChild(Path path, Path folder) {
        return folder != null && path.getParent() != null && path.getParent().equals(folder) && path.startsWith(folder);
    }

    private static boolean existsWithoutFollowingLinks(Path path) {
        return Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS)
                || Files.isSymbolicLink(path);
    }

    private static String fileIdentity(ResolvedFile resolved) {
        return resolved.resolvedPath == null ? null : fileIdentity(resolved.resolvedPath);
    }

    private static String fileIdentity(Path path) {
        try {
            Object fileKey = Files.readAttributes(path, java.nio.file.attribute.BasicFileAttributes.class).fileKey();
            return fileKey == null ? path.toRealPath().toString() : "key:" + fileKey;
        } catch (IOException e) {
            return null;
        }
    }

    private static boolean isSameFile(Path first, Path second) {
        try {
            return Files.isSameFile(first, second);
        } catch (IOException e) {
            return first.toAbsolutePath().normalize().equals(second.toAbsolutePath().normalize());
        }
    }

    private static void deleteIfExists(Path path) {
        try {
            Files.deleteIfExists(path);
        } catch (IOException ignored) {
            // Best effort cleanup of a temporary file. The original operation already failed.
        }
    }

    private static DeletionBackup moveToDeletionBackup(ResolvedFile resolved) {
        Path targetBackup = null;
        Path linkBackup = null;
        try {
            if (resolved.isSymbolicLink) {
                targetBackup = Files.createTempFile(resolved.recordedPath.getParent(), ".archunit-delete-target-", ".tmp");
                Files.move(resolved.resolvedPath, targetBackup, StandardCopyOption.REPLACE_EXISTING);
                linkBackup = Files.createTempFile(resolved.recordedPath.getParent(), ".archunit-delete-link-", ".tmp");
                Files.move(resolved.recordedPath, linkBackup, StandardCopyOption.REPLACE_EXISTING);
            } else {
                targetBackup = Files.createTempFile(resolved.recordedPath.getParent(), ".archunit-delete-", ".tmp");
                Files.move(resolved.recordedPath, targetBackup, StandardCopyOption.REPLACE_EXISTING);
            }
            return new DeletionBackup(targetBackup, linkBackup, resolved.recordedPath, resolved.resolvedPath);
