+    private IntegrityReport inspect(File folder, Properties properties, RuleViolationFileNameStrategy strategy) {
+        List<Entry> entries = new ArrayList<>();
+        List<String> descriptions = new ArrayList<>(properties.stringPropertyNames());
+        Collections.sort(descriptions);
+        for (String description : descriptions) {
+            String recordedName = properties.getProperty(description);
+            String derivedName = nameForInspection(strategy, description);
+            ResolvedFile resolved = resolveFile(folder, recordedName);
+            Entry entry = new Entry(description, recordedName, derivedName, resolved);
+            entry.broken = !resolved.isValidRegularFile();
+            entry.resolved = entry.isValid() && readLines(resolved.resolvedPath).isEmpty();
+            entry.misplaced = !recordedName.equals(derivedName);
+            entries.add(entry);
+        }
+
+        markShared(entries);
+        Map<String, Integer> derivedNameCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            derivedNameCounts.put(entry.derivedName, derivedNameCounts.getOrDefault(entry.derivedName, 0) + 1);
+        }
+        for (Entry entry : entries) {
+            entry.colliding = derivedNameCounts.get(entry.derivedName) > 1;
+            entry.occupied = entry.misplaced && isOccupiedDerivedName(folder, properties, entry);
+            entry.protectedIndex = entry.resolved.resolvedPath != null
+                    && isSameFile(entry.resolved.resolvedPath, new File(folder, STORED_RULES_FILE_NAME).toPath());
+            if (entry.protectedIndex) {
+                entry.occupied = true;
+            }
+        }
+
+        Set<String> ownedFiles = new HashSet<>();
+        for (Entry entry : entries) {
+            String identity = fileIdentity(entry.resolved);
+            if (identity != null) {
+                ownedFiles.add(identity);
+            }
+        }
+        List<Path> unownedFiles = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(folder.toPath())) {
+            for (Path file : files) {
+                if (file.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
+                    continue;
+                }
+                if (Files.isRegularFile(file) && !ownedFiles.contains(fileIdentity(file))) {
+                    unownedFiles.add(file);
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        unownedFiles.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private String nameForInspection(RuleViolationFileNameStrategy strategy, String description) {
+        String result = strategy.createRuleFileName(description);
+        if (result == null || result.trim().isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private void markShared(List<Entry> entries) {
+        Map<String, List<Entry>> byRecordedName = new HashMap<>();
+        Map<String, List<Entry>> byFile = new HashMap<>();
+        for (Entry entry : entries) {
+            byRecordedName.computeIfAbsent(normalize(entry.recordedName), ignored -> new ArrayList<>()).add(entry);
+            String identity = fileIdentity(entry.resolved);
+            if (identity != null) {
+                byFile.computeIfAbsent(identity, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+        for (List<Entry> group : byRecordedName.values()) {
+            if (group.size() > 1) {
+                group.forEach(entry -> entry.shared = true);
+            }
+        }
+        for (List<Entry> group : byFile.values()) {
+            if (group.size() > 1) {
+                group.forEach(entry -> entry.shared = true);
+            }
+        }
+    }
+
+    private boolean isOccupiedDerivedName(File folder, Properties properties, Entry entry) {
+        Path derivedPath = folder.toPath().resolve(entry.derivedName).normalize();
+        if (!isDirectChild(derivedPath, folder.toPath()) || entry.derivedName.equals(STORED_RULES_FILE_NAME)) {
+            return true;
+        }
+        if (existsWithoutFollowingLinks(derivedPath)) {
+            return true;
+        }
+        for (String description : properties.stringPropertyNames()) {
+            if (!description.equals(entry.description)
+                    && normalize(properties.getProperty(description)).equals(normalize(entry.derivedName))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private boolean repair(File folder, Properties properties, IntegrityReport report) {
+        boolean changed = false;
+        for (Entry entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                if (entry.protectedIndex) {
+                    throw new StoreInitializationFailedException("Refusing to delete the stored.rules index");
+                }
+                deleteEntryFile(entry);
+                properties.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                if (entry.protectedIndex) {
+                    throw new StoreInitializationFailedException("Refusing to move the stored.rules index");
+                }
+                Path target = folder.toPath().resolve(entry.derivedName).normalize();
+                try {
+                    Files.move(entry.resolved.resolvedPath, target);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Could not move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
+                }
+                properties.setProperty(entry.description, ensureUnixLineBreaks(entry.derivedName));
+                changed = true;
+            }
+        }
+        return changed;
+    }
+
+    private void deleteEntryFile(Entry entry) {
+        try {
+            if (entry.resolved.isSymbolicLink) {
+                Files.deleteIfExists(entry.resolved.resolvedPath);
+                Files.deleteIfExists(entry.resolved.recordedPath);
+            } else {
+                Files.deleteIfExists(entry.resolved.recordedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not delete violation file for rule '%s'", entry.description), e);
+        }
+    }
