+    private ResolvedFile resolveFile(String fileName) {
+        return resolveFile(storeFolder, fileName);
+    }
+
+    private static ResolvedFile resolveFile(File folder, String fileName) {
+        Path folderPath = folder.toPath();
+        Path recordedPath = folderPath.resolve(fileName).normalize();
+        boolean lexicallyInside = isDirectChild(recordedPath, folderPath);
+        if (!lexicallyInside) {
+            return new ResolvedFile(recordedPath, false, false, false, false, null, false);
+        }
+        boolean exists = existsWithoutFollowingLinks(recordedPath);
+        boolean symbolicLink = Files.isSymbolicLink(recordedPath);
+        if (!exists) {
